	private function publicOrderScope(): string {
		return "`o`.`customer_id` = '" . (int)$this->customer->getId() . "' AND `o`.`customer_id` != '0' AND `o`.`store_id` = '" . (int)$this->config->get('config_store_id') . "' AND `o`.`order_status_id` > '0' AND " . Acc007OrderStatus::visibleSql('`o`.`order_status_id`');
	}

	private function publicOrderSelect(): string {
		// Only the latest appended history can attest the CURRENT state. An old occurrence of
		// a recurring status, an undated row or an admin save without history gives unknown time.
		return "SELECT `o`.*, (SELECT CASE WHEN `last`.`order_status_id` = `o`.`order_status_id` THEN `last`.`date_added` ELSE NULL END FROM `" . DB_PREFIX . "order_history` `last` WHERE `last`.`order_id` = `o`.`order_id` ORDER BY `last`.`order_history_id` DESC LIMIT 1) AS `bs_status_date_added` FROM `" . DB_PREFIX . "order` `o`";
	}
}
